import { Gantt } from "march/components/gantt"

// bir bahçenin mevsimi: ekim, filizlenme, hasat; her biri bir öncekinden sonra gelir, hasat bir dönüm noktası
const iso = (offset: number) => { const d = new Date(); d.setDate(d.getDate() + offset); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}` }
const garden = [
  { id: "soil", name: "🪱 Toprağı hazırla", start: iso(-6), end: iso(-3), progress: 1, color: "brand-gold" as const },
  { id: "seed", name: "🌱 Tohum ek", start: iso(-2), end: iso(0), progress: 0.7, deps: ["soil"], color: "brand-green" as const },
  { id: "water", name: "💧 Düzenli sula", start: iso(1), end: iso(20), progress: 0, deps: ["seed"], color: "brand-blue" as const },
  { id: "harvest", name: "🍅 Hasat", start: iso(21), end: iso(21), milestone: true, deps: ["water"], color: "brand-orange" as const },
]

export function GardenPlan() {
  return <Gantt label="Bahçe planı" tasks={garden} editable={false} height={220} help={false} />
}

import { Gantt } from "march/components/gantt"
import { Card, Segmented } from "march/ui"

// bir konferansın hazırlık planı: ölçek seçilir, çubuklar sürüklenir, ardıl görevler kendiliğinden kayar
const iso = (offset: number) => { const d = new Date(); d.setDate(d.getDate() + offset); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}` }
type Task = { id: string; name: string; start: string; end: string; progress?: number; deps?: string[]; milestone?: boolean; color?: "brand-blue" | "brand-purple" | "brand-orange" | "brand-green" }

export function EventPlanning() {
  let $scale = "day"
  let $note = "Bir çubuğu sürükleyin"
  let $tasks: Task[] = [
    { id: "venue", name: "Mekân sözleşmesi", start: iso(-10), end: iso(-4), progress: 1, color: "brand-purple" },
    { id: "speakers", name: "Konuşmacı davetleri", start: iso(-5), end: iso(6), progress: 0.5, deps: ["venue"], color: "brand-blue" },
    { id: "tickets", name: "Bilet satışı", start: iso(0), end: iso(25), progress: 0.2, deps: ["venue"], color: "brand-green" },
    { id: "program", name: "Program yayını", start: iso(8), end: iso(8), milestone: true, deps: ["speakers"], color: "brand-orange" },
    { id: "day", name: "Konferans günü", start: iso(30), end: iso(30), milestone: true, deps: ["tickets", "program"], color: "brand-orange" },
  ]
  return <Card title="Konferans hazırlığı" subtitle={() => $note}>
    <Segmented aria-label="Ölçek" bind:value={$scale}
      options={[{ value: "day", label: "Gün" }, { value: "week", label: "Hafta" }, { value: "month", label: "Ay" }]} />
    <Gantt label="Konferans planı" tasks={() => $tasks} scale={() => $scale as "day"} cascade height={300}
      onChange={(t: Task) => { $tasks = $tasks.map((x) => (x.id === t.id ? t : x)); $note = `${t.name}: ${t.start} – ${t.end}` }}
      onSelect={(t: Task) => $note = `Seçildi: ${t.name}`} />
  </Card>
}

import { Gantt } from "march/components/gantt"
import { Button } from "march/ui"

// Gantt'ın bütün özellikleri bir arada: tasks (ilerleme, bağımlılık, renk, dönüm noktası), onChange, onSelect, scale,
// cascade, editable, arrows, height, rowHeight, todayLine, names, help, barLabel, labels, animate, label, class
const iso = (offset: number) => { const d = new Date(); d.setDate(d.getDate() + offset); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}` }
type Task = { id: string; name: string; start: string; end: string; progress?: number; deps?: string[]; milestone?: boolean; color?: "brand-blue" | "brand-pink" | "success" }

export function GanttLab() {
  let $edit = true
  let $arrows = true
  let $sel = "—"
  let $tasks: Task[] = [
    { id: "a", name: "Taslak", start: iso(-3), end: iso(1), progress: 0.8, color: "brand-blue" },
    { id: "b", name: "Gözden geçirme", start: iso(2), end: iso(5), progress: 0.25, deps: ["a"], color: "brand-pink" },
    { id: "c", name: "Onay", start: iso(6), end: iso(6), milestone: true, deps: ["b"], color: "success" },
  ]
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
      <Button size="sm" on:click={() => $edit = !$edit}>{() => ($edit ? "Kilitle" : "Düzenlemeyi aç")}</Button>
      <Button size="sm" on:click={() => $arrows = !$arrows}>{() => ($arrows ? "Okları gizle" : "Okları göster")}</Button>
    </div>
    <p sx={{ text: "sm", color: "muted" }}>{() => `Seçili: ${$sel}`}</p>
    <Gantt label="Yazı süreci" class="lab-gantt" tasks={() => $tasks} scale="day" cascade
      editable={() => $edit} arrows={() => $arrows} height={240} rowHeight={40} todayLine names animate
      help="Çubuğu sürükleyin; sağ ucundan uzatın."
      barLabel={(t: Task) => `${t.name} · %${Math.round((t.progress ?? 0) * 100)}`}
      labels={{ today: "Bugün", task: "Adım", days: (n: number) => `${n} gün` }}
      onChange={(t: Task) => $tasks = $tasks.map((x) => (x.id === t.id ? t : x))}
      onSelect={(t: Task) => $sel = t.name} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { GanttLab } from "./GanttLab.tsx"

// GanttLab'in testleri: kaydedince Testler sekmesinde çalışır
test("şema adını, sınıfını ve kendi sütun başlığını alır", () => {
  const s = renderTest(() => <GanttLab />)
  expect(s.get("[role=grid]")?.getAttribute("aria-label")).toBe("Yazı süreci")
  expect(s.get(".lab-gantt")).not.toBe(null)
  expect(s.sees("Adım")).toBe(true)
})

test("barLabel çubuğun metnine yüzdeyi ekler", () => {
  const s = renderTest(() => <GanttLab />)
  expect(s.sees("Taslak · %80")).toBe(true)
  expect(s.get('[data-task="a"]')?.getAttribute("aria-label")).toContain("Taslak")
})

test("görev adları sütunu her görevi yazar", () => {
  const s = renderTest(() => <GanttLab />)
  expect(s.all("[role=rowheader]").length).toBe(3)
})

test("kilitle düğmesi metnini değiştirir", async () => {
  const s = renderTest(() => <GanttLab />)
  await s.click("Kilitle")
  expect(s.sees("Düzenlemeyi aç")).toBe(true)
})
